  '/shops',
  createMiddleware<{ Variables: { shops: Shop[] } }>(async (c) => {
    const shops = await getShops()
    c.set('shops', shops)
  }),
  ssgParams(async (c) => {
    return c.var.shops.map((shop) => ({ id: shop.id }))
  }),
  async (c) => {
    return c.render(
      <div>
        <h1>ラーメン屋さん</h1>
        <ul>
          {c.var.shops.map((shop) => {
            return (
              <li>
                <a href={`/shops/${shop.id}`}>{shop.name}</a>
              </li>
            )
          })}
        </ul>
      </div>
    )
  }
)
```

